null_rate_checks.query:
SELECT count(*)::int AS null_count
          FROM "foundation_directory"
          WHERE "website" IS NULL;

SELECT count(*)::int AS null_count
          FROM "foundation_directory"
          WHERE "giving_total" IS NULL AND "asset_amount" IS NULL;

SELECT count(*)::int AS null_count
          FROM "foundation_directory"
          WHERE "email" IS NULL;

SELECT count(*)::int AS null_count
          FROM "foundation_directory"
          WHERE cardinality(contact_emails) = 0 OR contact_emails IS NULL;

SELECT count(*)::int AS null_count
          FROM "nonprofits"
          WHERE "website" IS NULL;

SELECT count(*)::int AS null_count
          FROM "nonprofits"
          WHERE "officer_email" IS NULL;

SELECT count(*)::int AS null_count
          FROM "nonprofits"
          WHERE "contact_emails" IS NULL;

SELECT count(*)::int AS null_count
          FROM "donor_discovery_directory"
          WHERE "website" IS NULL;

SELECT count(*)::int AS null_count
          FROM "donor_discovery_directory"
          WHERE "phone" IS NULL;

